const scores = $input.item.json.scores;
const ready = scores.filter(s => s.status === 'Ready').slice(0, 3);
const top = ready[0];
const as_of = $('Build as_of date').item.json.as_of;
return [{ json: { top_school: top, all_ready: ready, as_of } }];

const top = $('Extract top school').item.json.top_school;
const allReady = $('Extract top school').item.json.all_ready;
const as_of = $('Extract top school').item.json.as_of;
const rawText = $input.item.json.content[0].text;

let emailSubject = '';
let emailBody = rawText;
try {
  const subjectMatch = rawText.match(/^SUBJECT:\s*(.+)/m);
  const bodyMatch = rawText.match(/^BODY:\s*([\s\S]+)/m);
  if (subjectMatch && bodyMatch) {
    emailSubject = subjectMatch[1].trim();
    emailBody = bodyMatch[1].trim();
  }
} catch(e) {}

const gmailUrl = 'https://mail.google.com/mail/?view=cm&su=' + encodeURIComponent(emailSubject) + '&body=' + encodeURIComponent(emailBody);

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '\uD83D\uDD25 ' + allReady.length + ' school' + (allReady.length !== 1 ? 's' : '') + ' ready to buy \u00B7 ' + as_of }
  }
];

for (const school of allReady) {
  blocks.push({ type: 'divider' });
  const locationStr = (school.city && school.state) ? school.city + ', ' + school.state : '';
  const contactStr = (school.contact_name && school.contact_title) ? school.contact_name + ' (' + school.contact_title + ')' : '';
  const metaParts = [locationStr, contactStr].filter(Boolean);
  const metaLine = metaParts.length ? '\n_' + metaParts.join(' \u00B7 ') + '_' : '';
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '\uD83D\uDFE0 *' + school.name + '* \u00B7 PQL ' + school.pql_score + ' \u00B7 Ready' + metaLine + '\n' + school.reasons.map(r => '\u2022 ' + r).join('\n')
    }
  });
}

blocks.push({ type: 'divider' });
blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: '\u2709\uFE0F *Suggested outreach for ' + top.name + ':*\n' + (emailSubject ? '*Subject:* ' + emailSubject + '\n\n' : '') + emailBody
  }
});

blocks.push({
  type: 'actions',
  elements: [{
    type: 'button',
    text: { type: 'plain_text', text: 'Open draft in Gmail' },
    url: gmailUrl,
    style: 'primary'
  }]
});

return [{ json: { blocks } }];
